function toast(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3200)}
function msgError(e){console.error(e);toast('সমস্যা হয়েছে: '+(e.message||e));}
function dateNow(){const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function col(name){return db.collection(name)}
async function nextId(key,prefix,n){const ref=col('systemCounters').doc(key);return db.runTransaction(async tx=>{const s=await tx.get(ref),v=(s.exists?Number(s.data().value)||0:0)+1;tx.set(ref,{value:v,updatedAt:firebase.firestore.FieldValue.serverTimestamp()},{merge:true});return prefix+String(v).padStart(n,'0')})}
function showLogin(on){$('loginScreen').hidden=!on;$('app').hidden=on}

